3	/**
4	 * Thrown when a create request would exceed the daily cap: 100 or more owners have
5	 * already been created today (by registration date). Handled by
6	 * {@link OwnerDailyLimitExceededExceptionHandler}, which responds 429 Too Many Requests.
7	 */
8	public class OwnerDailyLimitExceededException extends Exception {
9	
10	    private final int count;
11	
12	    public OwnerDailyLimitExceededException(int count) {
13	        super("Daily owner creation limit reached: " + count + " owners already created today");
14	        this.count = count;
15	    }
16	
17	    public int getCount() {
18	        return count;
19	    }
