1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}:
9	 * CITY3 is the upper-cased first three letters of city, LAST3 the upper-cased first
10	 * three letters of lastName and NNNN a per-city 4-digit zero-padded sequence equal to
11	 * one more than the number of owners already in that city (e.g. {@code LON-SMI-0007}).
12	 * Runs after {@link BuildOwner} and before {@link SaveOwner}, so the sequence counts
13	 * existing owners in the city but not the one being created.
14	 */
15	public class AssignCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city = owner.getCity();
19	        String lastName = owner.getLastName();
20	        String cityPrefix = prefix(city);
21	        String lastPrefix = prefix(lastName);
22	        long sequence = 1L;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (equalsIgnoreCase(city, existing.getCity())) {
25	                sequence++;
26	            }
27	        }
28	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
29	    }
30	
31	    private static String prefix(String value) {
32	        String source = (value == null ? "" : value);
33	        return source.substring(0, Math.min(3, source.length())).toUpperCase();
34	    }
35	
36	    private static boolean equalsIgnoreCase(String a, String b) {
37	        return a == null ? b == null : a.equalsIgnoreCase(b);
38	    }
39	}
